import { plain } from './markdown.js';

function cleanSectionPlain(rawLines = []) {
  const filtered = rawLines
    .filter((ln) => !/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(ln))
    .map((ln) => (ln.includes('|') ? ln.replace(/^\s*\||\|\s*$/g, '').replace(/\s*\|\s*/g, ' · ') : ln));
  return plain(filtered.join('\n'));
}

/**
 * Splits Markdown document body into section chunks whose `id` (`s0`, `s1`, ...)
 * aligns 1-to-1 with heading IDs generated by `md()` in markdown.js.
 */
export function extractMarkdownSections(body = '', fallbackTitle = 'Overview', fallbackDesc = '') {
  const lines = String(body || '').split('\n');
  const sections = [];
  let tocIdx = 0;
  let inCode = false;
  let current = {
    id: '',
    title: fallbackTitle || 'Overview',
    level: 1,
    rawLines: [],
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^```/.test(line)) {
      inCode = !inCode;
      current.rawLines.push(line);
      continue;
    }
    if (!inCode) {
      const m = line.match(/^(?:\{align=(?:center|right)\}\s*)?(#{1,3})\s+(.*)/);
      if (m) {
        if (current.rawLines.join('').trim() || current.id) {
          sections.push({
            id: current.id,
            title: current.title,
            level: current.level,
            text: cleanSectionPlain(current.rawLines),
          });
        }
        const id = 's' + tocIdx++;
        const cleanTitle = m[2]
          .replace(/`([^`]+)`/g, '$1')
          .replace(/==(?:\[[a-z]+\])?([^=]+)==/g, '$1')
          .replace(/%%\[[a-z]+\]([^%]+)%%/g, '$1')
          .replace(/\+\+([^+]+)\+\+/g, '$1')
          .replace(/\*\*([^*]+)\*\*/g, '$1')
          .replace(/\*([^*]+)\*/g, '$1')
          .replace(/~~([^~]+)~~/g, '$1')
          .trim();
        current = {
          id,
          title: cleanTitle || fallbackTitle || 'Section',
          level: m[1].length,
          rawLines: [],
        };
        continue;
      }
    }
    current.rawLines.push(line);
  }

  const tailText = cleanSectionPlain(current.rawLines);
  if (tailText || current.id || !sections.length) {
    sections.push({
      id: current.id,
      title: current.title,
      level: current.level,
      text: tailText || String(fallbackDesc || ''),
    });
  }

  return sections;
}

/**
 * Extracts a concise, context-centered excerpt around matching query terms.
 */
export function extractBestExcerpt(text = '', expandedTerms = [], maxLen = 220) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return '';
  if (clean.length <= maxLen) return clean;

  const lower = clean.toLowerCase();
  let bestPos = -1;
  for (let i = 0; i < expandedTerms.length; i++) {
    const t = expandedTerms[i];
    if (!t || t.length < 2) continue;
    const idx = lower.indexOf(t.toLowerCase());
    if (idx !== -1 && (bestPos === -1 || idx < bestPos)) {
      bestPos = idx;
    }
  }

  if (bestPos <= 40) {
    return clean.slice(0, maxLen).replace(/\s+\S*$/, '') + '…';
  }

  const start = Math.max(0, bestPos - 55);
  const rawSlice = clean.slice(start, start + maxLen);
  const trimmed = start > 0 ? rawSlice.replace(/^\S*\s+/, '…') : rawSlice;
  return trimmed.replace(/\s+\S*$/, '') + (start + maxLen < clean.length ? '…' : '');
}

/**
 * Detects a Planit 13-slot wall/soffit type string inside user queries or cited docs.
 */
export function detectNamingCodeInText(text = '') {
  const m = String(text || '').match(/\b(C\d{4}\.\d{2}\.\d{2}_[A-Za-z0-9_/\-]+(?:\s*-\s*[A-Za-z0-9_.+-]+)?)/i);
  return m ? m[1].trim() : null;
}
